export interface ICourseCategoryModel {

    courseCategoryId: number;
    title: string;
    urlTitle: string;
    parentId: number;
}

export class CourseCategoryModel implements ICourseCategoryModel {

    courseCategoryId: number;
    title: string;
    urlTitle: string;
    parentId: number;

    constructor(
        courseCategoryId: number,
        title: string,
        urlTitle: string,
        parentId: number
    ) {
        if (courseCategoryId == null) {
            this.courseCategoryId = 0;
        } else {
            this.courseCategoryId = courseCategoryId;
        }

        this.title = title;
        this.urlTitle = urlTitle;
        this.parentId = parentId;
    }
}
